class Solution:
    def maskPII(self, s: str) -> str:
        if '@' in s:
            name, domain = s.split('@')
            return (name[0] + '*****' + name[-1] + '@' + domain).lower()
        digits = ''.join(c for c in s if c.isdigit())
        cc = len(digits) - 10
        prefix = ('+' + '*' * cc + '-') if cc else ''
        return prefix + '***-***-' + digits[-4:]

