class Solution {
public:
    string maskPII(string s) {
        if (s.find('@') != string::npos) {
            int at = s.find('@');
            string res;
            res += tolower(s[0]);
            res += "*****";
            res += tolower(s[at - 1]);
            res += '@';
            for (int i = at + 1; i < (int)s.size(); i++)
                res += tolower(s[i]);
            return res;
        }
        string digits;
        for (char c : s)
            if (isdigit((unsigned char)c)) digits += c;
        int cc = digits.size() - 10;
        string res;
        if (cc) { res += '+'; res.append(cc, '*'); res += '-'; }
        res += "***-***-";
        res += digits.substr(digits.size() - 4);
        return res;
    }
};

