class Solution {
    public String maskPII(String s) {
        if (s.indexOf('@') >= 0) {
            int at = s.indexOf('@');
            StringBuilder sb = new StringBuilder();
            sb.append(Character.toLowerCase(s.charAt(0)));
            sb.append("*****");
            sb.append(Character.toLowerCase(s.charAt(at - 1)));
            sb.append(s.substring(at).toLowerCase());
            return sb.toString();
        }
        StringBuilder d = new StringBuilder();
        for (char c : s.toCharArray())
            if (Character.isDigit(c)) d.append(c);
        int cc = d.length() - 10;
        StringBuilder sb = new StringBuilder();
        if (cc > 0) { sb.append('+'); for (int i = 0; i < cc; i++) sb.append('*'); sb.append('-'); }
        sb.append("***-***-");
        sb.append(d.substring(d.length() - 4));
        return sb.toString();
    }
}

