var maskPII = function(s) {
    if (s.includes('@')) {
        const [name, domain] = s.split('@');
        return (name[0] + '*****' + name[name.length - 1] + '@' + domain).toLowerCase();
    }
    const digits = [...s].filter(c => c >= '0' && c <= '9').join('');
    const cc = digits.length - 10;
    let res = cc ? '+' + '*'.repeat(cc) + '-' : '';
    return res + '***-***-' + digits.slice(-4);
};

