import re

class Solution:
    def maskPII(self, s: str) -> str:
        if '@' in s:
            m = re.match(r'^(.).*?(.@.*)$', s)
            return (m.group(1) + '*****' + m.group(2)).lower()
        digits = re.sub(r'\D', '', s)
        cc = len(digits) - 10
        prefix = f"+{'*' * cc}-" if cc else ''
        return prefix + '***-***-' + digits[-4:]

