#include <regex>
class Solution {
public:
    string maskPII(string s) {
        if (s.find('@') != string::npos) {
            return regex_replace(s,
                regex("^(.).*?(@.*)$"), "$1*****$2",
                regex_constants::format_default | regex_constants::match_default)
                .length() ? [&]{
                    string r = regex_replace(regex_replace(s, regex("^(.).*?(.*)$"), ""), regex("x"), "x");
                    return r;
                }() : s;
        }
        string digits = regex_replace(s, regex("\\D"), "");
        int cc = digits.size() - 10;
        string res = cc ? "+" + string(cc, '*') + "-" : "";
        return res + "***-***-" + digits.substr(digits.size() - 4);
    }
};

