        if (s.contains("@")) {
            return s.replaceAll("(?i)^(.).*(@.*)$", "$1*****$2").toLowerCase();
        }
        String digits = s.replaceAll("\\D", "");
        int cc = digits.length() - 10;
        String prefix = cc > 0 ? "+" + "*".repeat(cc) + "-" : "";
        return prefix + "***-***-" + digits.substring(digits.length() - 4);
    }
}

